ssize_t receive_and_process_message(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int msg_flags) {
    ssize_t bytes_received = -EAGAIN;
    int err = 0;

    if (sock->sk->sk_data_ready) {
        err = sock->ops->recvmsg(iocb, sock, msg, size, msg_flags, NULL);
        if (err > 0) {
            bytes_received = err;
            msg->msg_flags = msg_flags;
            sock->sk->sk_rx_queue = NULL;
            sock_update_rx_stats(sock, err);
        } else {
            bytes_received = err;
        }
    } else {
        while (1) {
            if (signal_pending(current)) {
                bytes_received = -EINTR;
                break;
            }

            if (sock->sk->sk_shutdown & RCV_SHUTDOWN) {
                bytes_received = 0;
                break;
            }

            if (msg_flags & MSG_DONTWAIT) {
                bytes_received = -EAGAIN;
                break;
            }

            wait_event_interruptible(sock->sk->wait, sock->sk->sk_data_ready ||
                                       sock->sk->sk_shutdown & RCV_SHUTDOWN);

            if (sock->sk->sk_data_ready) {
                err = sock->ops->recvmsg(iocb, sock, msg, size, msg_flags, NULL);
                if (err > 0) {
                    bytes_received = err;
                    msg->msg_flags = msg_flags;
                    sock->sk->sk_rx_queue = NULL;
                    sock_update_rx_stats(sock, err);
                    break;
                } else {
                    bytes_received = err;
                    break;
                }
            }
        }
    }

    return bytes_received;
}

int receive_and_process_message(struct kiocb *iocb, struct socket *sock,
                                struct msghdr *msg, size_t size, int msg_flags) {
    int ret;
    DECLARE_WAITQUEUE(wait, current);
    struct sock *sk = sock->sk;

    add_wait_queue(&sk->sk_wait, &wait);
    while (1) {
        set_current_state(TASK_INTERRUPTIBLE);

        if (sk->sk_err || (sk->sk_state == TCP_CLOSE))
            break;

        if (sk->sk_data_ready && sk->sk_data_ready(sk, size))
            break;

        if (signal_pending(current)) {
            ret = -ERESTARTSYS;
            break;
        }

        if (msg_flags & MSG_DONTWAIT) {
            ret = -EAGAIN;
            break;
        }

        schedule();
        continue;
    }

    if (!ret)
        ret = sock->ops->recvmsg(iocb, sock, msg, size, msg_flags);

    set_current_state(TASK_RUNNING);
    remove_wait_queue(&sk->sk_wait, &wait);

    if (ret > 0)
        msg->msg_flags = msg_flags;

    return ret;
}

#include <linux/socket.h>
#include <linux/ioctl.h>
#include <linux/errno.h>
#include <linux/wait.h>
#include <linux/sched.h>

int sock_rcv(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
             size_t size, int msg_flags) {
    int ret = 0;

    while (1) {
        ret = sock->ops->recvmsg(iocb, sock, msg, size, msg_flags);
        if (ret > 0) {
            // Successfully received message
            break;
        } else if (ret == -EAGAIN && (msg_flags & MSG_DONTWAIT)) {
            // Non-blocking and no message available
            break;
        } else if (ret == -ERESTARTSYS) {
            // Interrupted, retry
            continue;
        } else {
            // Some other error occurred
            break;
        }
    }

    return ret;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int msg_flags) {
    int ret;
    struct sock *sk = sock->sk;

    if (sk->sk_state == TCP_LISTEN)
        return -EOPNOTSUPP;

    while (1) {
        ret = sock->ops->recvmsg(iocb, sock, msg, size, msg_flags);
        if (ret != -EAGAIN) {
            if (ret > 0)
                atomic_add(ret, &sk->sk_ommsg);
            break;
        }

        if (msg_flags & MSG_DONTWAIT)
            return -EAGAIN;

        if (!wait_for_poll(sock, sock->ops->poll, NULL))
            continue;

        if (signal_pending(current))
            return -EINTR;
    }

    return ret;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int msg_flags) {
    int ret = 0;
    long timeout = 0;
    int nonblocking = msg_flags & MSG_DONTWAIT;

    if (nonblocking) {
        ret = sock->ops->recvmsg(iocb, sock, msg, size, msg_flags);
        if (ret != -EAGAIN && ret != -EWOULDBLOCK) {
            return ret;
        }
        return -EAGAIN;
    }

    while (1) {
        ret = sock->ops->recvmsg(iocb, sock, msg, size, msg_flags);
        if (ret > 0) {
            msg->msg_len = ret;
            sock->sk->sk_data_processed += ret;
            return ret;
        }

        if (ret != -EAGAIN && ret != -EWOULDBLOCK) {
            return ret;
        }

        if (timeout <= 0) {
            return -ETIMEDOUT;
        }

        schedule_timeout(timeout);
    }

    return ret;
}
